import { pastel } from 'gradient-string';
import cliSpinners from 'cli-spinners';
import axios from 'axios';
import { GeminiClient } from './gemini_client.js';
import { loadPromptTemplate } from './config_storage.js';

const CONFIG_FILE_PATH = path.join(process.env.HOME, 'auroraphtgrp01.json');
const VERSION = '1.0.8';
const args = process.argv.slice(2);
const options = { 'autoAdd': args.includes('-a'), 'autoPush': args.includes('-p') };

function debug(...args) {
  if (process.env.DEBUG) console.log(...args);
}

const CUSTOM_MESSAGE_OPTION = '[write own message]...';
const spinner = ora({ spinner: cliSpinners.dots, color: 'cyan' });

async function displayIntro() {
  console.log(chalk.hex('#A8E6CF')('🗒️ Version: ' + chalk.bold(VERSION)));
  console.log();
  console.log(pastel('✨ Welcome to Auroraphtgrp - Auto Generate Commit Messages ✨'));
  console.log(chalk.hex('#FFAAA5')('================================================================='));
  if (options.autoAdd || options.autoPush) {
    console.log(chalk.hex('#A8E6CF')('Active options: ' + (options.autoAdd ? '[-a] auto-add ' : '') + (options.autoPush ? '[-p] auto-push' : '')));
  }
  console.log(chalk.hex('#A8E6CF')('================================================================='));
}

function checkGitRepository() {
  try {
    execSync('git rev-parse --is-inside-work-tree', { stdio: 'ignore' });
    return true;
  } catch {
    return false;
  }
}

function checkConfigFile() {
  if (!fs.existsSync(CONFIG_FILE_PATH)) {
    console.error(chalk.hex('#FF6F61').bold('❌ Error: Configuration file not found!'));
    console.error(chalk.hex('#FF6F61')('Please create the auroraphtgrp01.json file in the current directory.'));
    console.error(chalk.hex('#FF6F61')('The file should contain your Gemini API token in the following format:'));
    console.error(chalk.hex('#FF6F61')('{'));
    console.error(chalk.hex('#A8E6CF')('  "geminiToken": "YOUR_GEMINI_API_TOKEN"'));
    console.error(chalk.hex('#FF6F61')('}'));
    console.error(chalk.hex('#FF6F61')('You can get an API key from https://makersuite.google.com/app/apikey'));
    return false;
  }
  return true;
}

function getStagedChanges() {
  try {
    const output = execSync('git diff --staged', { encoding: 'utf8' });
    return output;
  } catch (err) {
    console.error(chalk.hex('#FF6F61').bold('❌ Failed to get staged changes:'), err);
    return null;
  }
}

async function trackUserCommit() {
  try {
    const userName = execSync('git config user.name', { encoding: 'utf8' }).trim();
    const email = execSync('git config user.email', { encoding: 'utf8' }).trim();
    await axios.post('https://api.uniko.id.vn/api/users/tracking-usage-library', { userName, email });
  } catch (err) {
    debug('Failed to track user commit:', err);
  }
}

async function getMessages(client, prompt) {
  try {
    const response = await client.getMessages(prompt);
    debug('response:', response);

    // Message normalization and filtering logic omitted for brevity
    // Returns an array of commit message suggestions including CUSTOM_MESSAGE_OPTION

    return response;
  } catch (err) {
    spinner.fail(chalk.hex('#FF6F61')('❌ API Token Error: You need to set up geminiToken in the configuration file'));
    if (err instanceof Error && err.message.includes('Unauthorized')) {
      console.log(chalk.hex('#FF6F61')('🔄 Retrying with authentication...'));
      return getMessages(client, prompt);
    } else {
      console.error(chalk.hex('#FF6F61')('❌ Error: ' + (err instanceof Error ? err.message : 'Unknown error')));
      throw err;
    }
  }
}

async function pushChanges() {
  const spinnerPush = ora({ text: chalk.hex('#A8E6CF')('🚀 Pushing changes to remote...'), spinner: cliSpinners.dots }).start();
  try {
    const output = execSync('git push', { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf8' });
    spinnerPush.succeed(chalk.hex('#A8E6CF')('✅ Changes pushed successfully!'));
    console.log(chalk.hex('#FFD3B6')(output));
  } catch (err) {
    spinnerPush.fail(chalk.hex('#FF6F61')('❌ Failed to push changes'));
    if (err instanceof Error) {
