import { homedir } from 'os';
import { readFileSync, writeFileSync, existsSync } from 'fs';
import { defaultPromptTemplate } from './template.js';
import { join } from 'path';

const GLOBAL_CONFIG_PATH = homedir() + '/auroraphtgrp01.json';
const LOCAL_CONFIG_PATH = process.cwd() + '/auroraphtgrp01.json';
const GLOBAL_PROMPT_TEMPLATE_PATH = homedir() + '/.commitgpt-template';
const LOCAL_PROMPT_TEMPLATE_PATH = process.cwd() + '/.commitgpt-template';

const defaultConfig = { 'model': 'gemini-pro', 'temperature': 0.5, 'maxTokens': 2048, 'geminiToken': '' };

const writeJsonFile = (path, data) => {
  writeFileSync(path, JSON.stringify(data, null, 2));
};

function ensureGlobal() {
  if (!existsSync(GLOBAL_CONFIG_PATH)) writeJsonFile(GLOBAL_CONFIG_PATH, {});
}

function loadGlobal() {
  return existsSync(GLOBAL_CONFIG_PATH) ? JSON.parse(readFileSync(GLOBAL_CONFIG_PATH, 'utf-8')) : {};
}

function loadLocal() {
  return existsSync(LOCAL_CONFIG_PATH) ? JSON.parse(readFileSync(LOCAL_CONFIG_PATH, 'utf-8')) : {};
}

let cache = null;

function load() {
  if (cache) return cache;
  ensureGlobal();
  const globalConfig = loadGlobal();
  const localConfig = loadLocal();
  return (cache = { ...defaultConfig, ...globalConfig, ...localConfig });
}

function assertTempValid(template) {
  if (!template.includes('{{diff}}')) throw new Error('Template must include {{diff}}');
}

export function loadPromptTemplate() {
  const localTemplatePath = join(process.cwd(), '.commitgpt-template');
  if (existsSync(localTemplatePath)) {
    try {
      const content = readFileSync(localTemplatePath, 'utf-8');
      assertTempValid(content);
      return content;
    } catch (e) {
      console.error('Failed to read template file:', e);
    }
  }
  if (existsSync(LOCAL_PROMPT_TEMPLATE_PATH)) {
    const content = readFileSync(LOCAL_PROMPT_TEMPLATE_PATH, 'utf-8');
    assertTempValid(content);
    return content;
  }
  if (existsSync(GLOBAL_PROMPT_TEMPLATE_PATH)) {
    const content = readFileSync(GLOBAL_PROMPT_TEMPLATE_PATH, 'utf-8');
    assertTempValid(content);
    return content;
  }
  return defaultPromptTemplate;
}

export function getConfig(key) {
  const config = load();
  return config[key];
}

export function setGlobalConfig(key, value) {
  const globalConfig = loadGlobal();
  globalConfig[key] = value;
  writeJsonFile(GLOBAL_CONFIG_PATH, globalConfig);
}

export function loadConfig() {
  return load();
}

