import { GoogleGenerativeAI } from '@google/generative-ai';
import { getConfig } from './config_storage.js';
import chalk from 'chalk';
import ora from 'ora';
import cliSpinners from 'cli-spinners';

export class GeminiClient {
  constructor() {
    const geminiToken = getConfig('geminiToken');
    if (!geminiToken) {
      console.error(chalk.hex('#FFB88C')('❌ Error calling Gemini API'));
      console.error(chalk.hex('#FFB88C')('Please set the ' + chalk.bold('geminiToken') + ' in your config file'));
      console.error(chalk.hex('#FFB88C')('You can get an API key from https://makersuite.google.com/app/apikey'));
      throw new Error('geminiToken is not set');
    }
    console.log(chalk.cyan('🔍 Initializing Gemini AI client...'));
    this.genAI = new GoogleGenerativeAI(geminiToken);
    const model = getConfig('model');
    this.getAnswer = this.genAI.getGenerativeModel({ model });
  }

  async generateContent(prompt) {
    const spinner = ora({
      text: chalk.cyan('🔎 Querying Gemini AI...'),
      spinner: cliSpinners.dots,
      color: '#FF6F61'
    }).start();

    try {
      const response = await this.getAnswer(prompt);
      const answer = await response.text();
      spinner.succeed(chalk.green('✅ Received response from Gemini AI\n'));
      return answer;
    } catch (error) {
      spinner.fail(chalk.hex('#FF6F61')('❌ Error calling Gemini API'));
      console.error(chalk.hex('#FF6F61')('Error details: ' + (error instanceof Error ? error.message : String(error))));
      throw error;
    }
  }
}

